function triageBody(lines) {
  return [
    '> *This was generated by AI during triage.*',
    '',
    ...lines,
  ].join('\n');
}

function requireText(value, name) {
  if (!value || typeof value !== 'string') {
    throw new Error(`${name} is required`);
  }
  return value;
}

function requireNumber(value, name) {
  const number = Number(value);
  if (!Number.isInteger(number) || number <= 0) {
    throw new Error(`${name} must be a positive integer`);
  }
  return number;
}

function failedCheck(statusCheckRollup = []) {
  return statusCheckRollup.find((check) => {
    const conclusion = String(check.conclusion ?? '').toUpperCase();
    return ['FAILURE', 'TIMED_OUT', 'CANCELLED', 'ACTION_REQUIRED'].includes(conclusion);
  }) ?? null;
}

function repairForPullRequest({ runId, issueNumber, pullRequest }) {
  const check = failedCheck(pullRequest.statusCheckRollup);
  let reason = null;
  let summary = null;

  if (check) {
    reason = 'ci-failed';
    summary = `CI check failed: ${check.name ?? 'unnamed check'}.`;
  } else if (String(pullRequest.reviewDecision ?? '').toUpperCase() === 'CHANGES_REQUESTED') {
    reason = 'review-changes-requested';
    summary = 'Review requested changes.';
  }

  if (!reason) {
    return null;
  }

  return {
    run_id: `${runId}-repair-1`,
    parent_run_id: runId,
    issue_number: issueNumber,
    pull_request: {
      number: pullRequest.number,
      url: pullRequest.url,
    },
    reason,
    summary,
  };
}

function checksPassed(statusCheckRollup = []) {
  if (!statusCheckRollup.length) {
    return false;
  }

  return statusCheckRollup.every((check) => {
    const conclusion = String(check.conclusion ?? '').toUpperCase();
    return ['SUCCESS', 'SKIPPED', 'NEUTRAL'].includes(conclusion);
  });
}

function isMergeReady(pullRequest) {
  const mergeState = String(pullRequest.mergeStateStatus ?? '').toUpperCase();
  const reviewDecision = String(pullRequest.reviewDecision ?? '').toUpperCase();
  return String(pullRequest.state ?? '').toUpperCase() === 'OPEN'
    && mergeState === 'CLEAN'
    && ['APPROVED', ''].includes(reviewDecision)
    && checksPassed(pullRequest.statusCheckRollup);
}

function isMerged(pullRequest) {
  return String(pullRequest.state ?? '').toUpperCase() === 'MERGED' || Boolean(pullRequest.mergedAt);
}

export function createPrOwnershipLoop(options = {}) {
  const issueClient = options.issueClient;
  const pullRequestClient = options.pullRequestClient;
  const runEventLog = options.runEventLog;

  return {
    async observePullRequest(request) {
      const repository = requireText(request.repository, 'repository');
      const issueNumber = requireNumber(request.issueNumber, 'issueNumber');
      const runId = requireText(request.runId, 'runId');
      const pullRequestNumber = requireNumber(request.pullRequestNumber, 'pullRequestNumber');
      const pullRequest = await pullRequestClient.viewPullRequest({
        repository,
        number: pullRequestNumber,
      });

      await runEventLog.append({
        runId,
        type: 'pr.observed',
        summary: `Observed PR #${pullRequest.number}: ${pullRequest.state}.`,
      });

      const repair = repairForPullRequest({ runId, issueNumber, pullRequest });
      if (!repair) {
        if (isMerged(pullRequest)) {
          await runEventLog.append({
            runId,
            type: 'completion',
            summary: `PR #${pullRequest.number} merged.`,
          });
          await issueClient.createComment({
            repository,
            issueNumber,
            body: triageBody([
              '## Pull request merged',
              '',
              `- PR: ${pullRequest.url}`,
              '- Issue closure should be handled by GitHub linking or configured repository policy.',
            ]),
          });

          return {
            status: 'merged',
            pullRequest,
          };
        }

        if (isMergeReady(pullRequest)) {
          await runEventLog.append({
            runId,
            type: 'pr.merge-ready',
            summary: `PR #${pullRequest.number} is merge-ready.`,
          });
          await issueClient.createComment({
            repository,
            issueNumber,
            body: triageBody([
              '## Merge ready',
              '',
              `- PR: ${pullRequest.url}`,
              '- Auto-merge: disabled',
            ]),
          });

          return {
            status: 'merge-ready',
            pullRequest,
            auto_merge: false,
          };
        }

        return {
          status: 'waiting',
          pullRequest,
        };
      }

      await runEventLog.append({
        runId,
        type: 'repair.scheduled',
        summary: repair.summary,
      });
      await issueClient.createComment({
        repository,
        issueNumber,
        body: triageBody([
          '## Repair scheduled',
          '',
          `- PR: ${pullRequest.url}`,
          `- Repair run: ${repair.run_id}`,
          `- Reason: ${repair.summary}`,
        ]),
      });

      return {
        status: 'repair-scheduled',
        repair,
      };
    },
  };
}
